SELECT ${params.xColumn}, ROUND(sum(${params.yColumn}),1) total FROM dish_info
 1=1 ${ew.sqlSegment}
group by ${params.xColumn}
limit 12

select.if:
SELECT DATE_FORMAT(${params.xColumn},'%Y-%m-%d') ${params.xColumn}, sum(${params.yColumn}) total FROM dish_info
 1=1 ${ew.sqlSegment}
group by DATE_FORMAT(${params.xColumn},'%Y-%m-%d')

SELECT DATE_FORMAT(${params.xColumn},'%Y-%m') ${params.xColumn}, sum(${params.yColumn}) total FROM dish_info
 1=1 ${ew.sqlSegment}
group by DATE_FORMAT(${params.xColumn},'%Y-%m')

SELECT DATE_FORMAT(${params.xColumn},'%Y') ${params.xColumn}, sum(${params.yColumn}) total FROM dish_info
 1=1 ${ew.sqlSegment}
group by DATE_FORMAT(${params.xColumn},'%Y')

mapper.select:
